use super::{self as claims,*};
use crate::platform::{NovelId,NovelIdReservation,ObjectPrefix,WriteFence};
fn record(id:i64)->NovelRecord{serde_json::from_value(serde_json::json!({"id":id,"author":"author","title":"title","file_title":"target","toc_url":"https://example.test/book/","sitename":"Test","last_update":"2026-11-15T00:00:00Z"})).unwrap()}
fn prefix(record:&NovelRecord)->ObjectPrefix{ObjectPrefix::from(NovelObjectKeys::new(&record.sitename,&record.file_title,record.use_subdirectory).unwrap().prefix().clone())}
fn store_gate(root:&std::path::Path,prefix:&ObjectPrefix,epoch:u64,closed:bool,owner:Option<&str>,origin:&str){
    // Write through the production gate writer so the scan-invalidation
    // counter advances exactly like a real gate mutation does (issue #58).
    let prefix=prefix.as_ref().trim_end_matches('/');let archive_root=root.join(crate::downloader::types::ARCHIVE_ROOT_DIR);let directory=archive_root.join(".objects/.narou-transfer/.gate");std::fs::create_dir_all(&directory).unwrap();let owner=if closed{Some(owner.unwrap_or("test-closed-owner"))}else{None};let path=directory.join(crate::application::transfer::sha256_hex(prefix.as_bytes()));crate::native::object_store::write_gate_file(&archive_root,&path,&serde_json::to_vec(&serde_json::json!({"prefix":prefix,"epoch":epoch,"owner":owner,"origin_url_fold":origin,"updated_at":0,"readers":{},"content_revision":0,"migrated":false})).unwrap()).unwrap();
}

#[test]
fn active_claim_rejects_new_or_moved_identity_but_preserves_legacy_duplicate(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();connection.execute_batch(SCHEMA).unwrap();let target=record(9);let prefix=prefix(&target);claim(root.path(),&connection,&claims::PublicationClaim{owner:"session:0:plan",session:"session",publication:0,revision:"plan"},9,&target.toc_url,prefix.as_ref()).unwrap();let before=BTreeMap::from([(7,record(7))]);let guard=record_claim_guard_conn(root.path(),&connection,&before,None).unwrap();let mut unchanged=record(7);unchanged.title="ordinary title edit".into();guard.validate(&BTreeMap::from([(7,unchanged)])).unwrap();assert!(guard.validate(&BTreeMap::from([(8,record(8))])).is_err());let mut moved=record(7);moved.file_title="moved".into();assert!(guard.validate(&BTreeMap::from([(7,moved)])).is_err());
}

#[test]
fn transfer_marker_authorizes_only_exact_publication_assigned_identity(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();connection.execute_batch(SCHEMA).unwrap();let target=record(9);let prefix=prefix(&target);claim(root.path(),&connection,&claims::PublicationClaim{owner:"session:0:plan",session:"session",publication:0,revision:"plan"},9,&target.toc_url,prefix.as_ref()).unwrap();let receipt=crate::application::transfer::PublicationReceipt{novel_ordinal:0,action:crate::application::transfer::PlanAction::Create,outcome:"created".into(),assigned_id:Some(9),files_installed:1,error:None};let marker=TransferCommitMarker{session_id:"session".into(),publication_id:0,novel_id:NovelId(9),receipt:serde_json::to_vec(&receipt).unwrap(),yaml_commit_path:"committed".into()};let guard=record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),Some(&marker)).unwrap();guard.validate(&BTreeMap::from([(9,target.clone())])).unwrap();let mut moved=target;moved.file_title="foreign".into();assert!(guard.validate(&BTreeMap::from([(9,moved)])).is_err());let mut wrong=marker;wrong.session_id="other-session".into();let guard=record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),Some(&wrong)).unwrap();assert!(guard.validate(&BTreeMap::from([(9,record(9))])).is_err());
}

#[test]
fn ordinary_generation_epoch_and_identity_are_all_required_and_release_is_fenced(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();let target=record(12);let prefix=prefix(&target);let fence=WriteFence::new(prefix.clone(),4);let reservation=NovelIdReservation::new(NovelId(12),71);reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&target.toc_url,true).unwrap();reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&target.toc_url,false).unwrap();assert!(connection.query_row("SELECT empty_owned FROM native_transfer_target_claims WHERE novel_id=12",[],|row|row.get::<_,bool>(0)).unwrap());let mut guard=record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),None).unwrap();assert!(guard.validate(&BTreeMap::from([(12,target.clone())])).is_err());assert!(guard.authorize_ordinary(12,70,&prefix,4).is_err());assert!(guard.authorize_ordinary(12,71,&prefix,5).is_err());guard.authorize_ordinary(12,71,&prefix,4).unwrap();guard.validate(&BTreeMap::from([(12,target.clone())])).unwrap();let mut moved=target;moved.toc_url="https://example.test/foreign/".into();assert!(guard.validate(&BTreeMap::from([(12,moved)])).is_err());release_ordinary_claim_conn(&connection,12,70).unwrap();assert!(consume_ordinary_claim_conn(&connection,12,70,&prefix,4).is_err());assert!(consume_ordinary_claim_conn(&connection,12,71,&prefix,5).is_err());consume_ordinary_claim_conn(&connection,12,71,&prefix,4).unwrap();assert_eq!(connection.query_row("SELECT COUNT(*) FROM native_transfer_target_claims",[],|row|row.get::<_,i64>(0)).unwrap(),0);
}

