#[test]
fn overlapping_claims_reject_new_bindings_but_preserve_unchanged_legacy_rows(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();connection.execute_batch(SCHEMA).unwrap();let old=record(12);let child=prefix(&old);let parent=child.as_ref().trim_end_matches('/').rsplit_once('/').unwrap().0;claim(root.path(),&connection,&claims::PublicationClaim{owner:"parent-owner",session:"session",publication:3,revision:"plan"},99,"https://example.test/parent/",parent).unwrap();claim(root.path(),&connection,&claims::PublicationClaim{owner:"sibling-owner",session:"session",publication:4,revision:"plan"},98,"https://example.test/sibling/",&format!("{parent}-sibling")).unwrap();let before=BTreeMap::from([(12,old.clone())]);let guard=record_claim_guard_conn(root.path(),&connection,&before,None).unwrap();let mut unchanged=old.clone();unchanged.title.push_str(" updated");guard.validate(&BTreeMap::from([(12,unchanged)])).unwrap();let mut foreign=old;foreign.id=13;foreign.toc_url="https://example.test/new/".into();assert!(guard.validate(&BTreeMap::from([(13,foreign.clone())])).is_err());let fence=WriteFence::new(child,4);let reservation=NovelIdReservation::new(NovelId(13),82);assert!(reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&foreign.toc_url,true).is_err());
}

