#[test]
fn changed_identity_cannot_enter_nested_current_namespace(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();let mut child=record(2);child.file_title="n1234ab".into();child.use_subdirectory=true;child.toc_url="https://example.test/child/".into();let child_prefix=prefix(&child);let parent_prefix=child_prefix.as_ref().trim_end_matches('/').rsplit_once('/').unwrap().0;let mut parent=record(1);parent.file_title=parent_prefix.rsplit('/').next().unwrap().into();parent.use_subdirectory=false;assert!(crate::platform::access_fence::namespace_prefixes_overlap(prefix(&parent).as_ref(),child_prefix.as_ref()));let mut unrelated=child.clone();unrelated.use_subdirectory=false;unrelated.file_title="unrelated".into();let before=BTreeMap::from([(1,parent.clone()),(2,unrelated)]);let guard=record_claim_guard_conn(root.path(),&connection,&before,None).unwrap();assert!(guard.validate(&BTreeMap::from([(1,parent.clone()),(2,child.clone())])).is_err());let legacy=BTreeMap::from([(1,parent),(2,child)]);let guard=record_claim_guard_conn(root.path(),&connection,&legacy,None).unwrap();let mut edited=legacy;edited.get_mut(&2).unwrap().title="safe existing metadata edit".into();guard.validate(&edited).unwrap();
}

#[test]
fn removal_allows_only_its_exact_ordinary_pending_cleanup_claim(){
    let root=tempfile::tempdir().unwrap();let inventory=crate::db::inventory::Inventory::new(root.path().to_path_buf());let connection=Connection::open_in_memory().unwrap();let target=record(12);let fence=WriteFence::new(prefix(&target),4);store_gate(root.path(),&fence.prefix,4,false,None,"");let reservation=NovelIdReservation::new(NovelId(12),71);reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&target.toc_url,true).unwrap();assert_removal_identity(&inventory,None,&connection,&fence,NovelId(12)).unwrap();assert_eq!(crate::native::object_store::read_fs_gate_origin(root.path(),&fence.prefix).unwrap().unwrap(),crate::db::novel_codec::fold(&target.toc_url));assert!(assert_removal_identity(&inventory,None,&connection,&fence,NovelId(13)).is_err());let wrong_epoch=WriteFence::new(fence.prefix.clone(),5);assert!(assert_removal_identity(&inventory,None,&connection,&wrong_epoch,NovelId(12)).is_err());release_ordinary_claim_conn(&connection,12,71).unwrap();claim(root.path(),&connection,&claims::PublicationClaim{owner:"transfer-owner",session:"session",publication:0,revision:"plan"},12,&target.toc_url,fence.prefix.as_ref()).unwrap();assert!(assert_removal_identity(&inventory,None,&connection,&fence,NovelId(12)).is_err());
}

#[test]
fn removal_rejects_another_current_child_and_a_moved_own_prefix(){
    let root=tempfile::tempdir().unwrap();let inventory=crate::db::inventory::Inventory::new(root.path().to_path_buf());let connection=Connection::open_in_memory().unwrap();let mut child=record(2);child.file_title="n1234ab".into();child.use_subdirectory=true;child.toc_url="https://example.test/child/".into();let child_prefix=prefix(&child);let parent_prefix=child_prefix.as_ref().trim_end_matches('/').rsplit_once('/').unwrap().0;let mut parent=record(1);parent.file_title=parent_prefix.rsplit('/').next().unwrap().into();parent.use_subdirectory=false;let fence=WriteFence::new(prefix(&parent),4);store_gate(root.path(),&fence.prefix,4,false,None,"");let path=inventory.inventory_path("database",crate::db::inventory::InventoryScope::Local);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(&path,serde_yaml::to_string(&BTreeMap::from([(1,parent.clone()),(2,child)])).unwrap()).unwrap();assert!(assert_removal_identity(&inventory,None,&connection,&fence,NovelId(1)).is_err());std::fs::write(&path,serde_yaml::to_string(&BTreeMap::from([(1,parent.clone())])).unwrap()).unwrap();assert_removal_identity(&inventory,None,&connection,&fence,NovelId(1)).unwrap();parent.file_title="moved".into();std::fs::write(&path,serde_yaml::to_string(&BTreeMap::from([(1,parent)])).unwrap()).unwrap();assert!(assert_removal_identity(&inventory,None,&connection,&fence,NovelId(1)).is_err());
}

#[test]
fn retained_same_url_reuses_exact_prefix_but_rebinding_or_removed_namespace_is_denied(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();let target=record(12);let prefix=prefix(&target);let origin=crate::db::novel_codec::fold(&target.toc_url);store_gate(root.path(),&prefix,4,false,None,&origin);let guard=record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),None).unwrap();guard.validate(&BTreeMap::from([(12,target.clone())])).unwrap();let fence=WriteFence::new(prefix.clone(),4);let reservation=NovelIdReservation::new(NovelId(12),71);reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&target.toc_url,false).unwrap();release_ordinary_claim_conn(&connection,12,71).unwrap();let mut foreign=target.clone();foreign.toc_url="https://example.test/foreign/".into();assert!(guard.validate(&BTreeMap::from([(12,foreign.clone())])).is_err());assert!(reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&foreign.toc_url,false).is_err());let owner=format!("remove-v1:12:0:{}",uuid::Uuid::new_v4());store_gate(root.path(),&prefix,5,true,Some(&owner),&origin);let guard=record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),None).unwrap();assert!(guard.validate(&BTreeMap::from([(12,target.clone())])).is_err());assert!(reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&target.toc_url,false).is_err());
}

#[test]
fn closed_or_retained_parent_gate_protects_unregistered_child_and_full_unicode_descendants(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();let mut child=record(2);child.file_title="n1234ab".into();child.use_subdirectory=true;let child_prefix=prefix(&child);let parent=ObjectPrefix::new(child_prefix.as_ref().trim_end_matches('/').rsplit_once('/').unwrap().0).unwrap();let owner=format!("remove-v1:1:1:{}",uuid::Uuid::new_v4());store_gate(root.path(),&parent,5,true,Some(&owner),"");let fence=WriteFence::new(child_prefix.clone(),4);let reservation=NovelIdReservation::new(NovelId(2),71);let guard=record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),None).unwrap();assert!(guard.validate(&BTreeMap::from([(2,child.clone())])).is_err());assert!(reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&child.toc_url,true).is_err());store_gate(root.path(),&parent,6,false,None,"https://example.test/retained/");assert!(record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),None).unwrap().validate(&BTreeMap::from([(2,child)])).is_err());let target=record(9);let target_prefix=prefix(&target);let descendant=ObjectPrefix::new(format!("{}/\u{10ffff}/child",target_prefix.as_ref().trim_end_matches('/'))).unwrap();store_gate(root.path(),&descendant,4,false,None,"https://example.test/other/");assert!(record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),None).unwrap().validate(&BTreeMap::from([(9,target)])).is_err());
}

fn virtual_record(id:i64)->NovelRecord{let mut record=record(id);record.ncode=Some(crate::virtual_novel::ncode(id));record.file_title=crate::virtual_novel::ncode(id);record.toc_url=format!("https://narou.rs/virtual/{}",crate::virtual_novel::ncode(id));record.tags.push(crate::virtual_novel::tag(id));assert!(crate::virtual_novel::is_virtual_record(&record));record}

#[test]
fn portable_virtual_identity_cas_is_explicit_and_stale_legacy_writers_cannot_rewind_it(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();let original=virtual_record(12);let prefix=prefix(&original);let fence=WriteFence::new(prefix.clone(),7);let observed=original.toc_url.clone();let origin=crate::db::novel_codec::fold(&observed);let candidate=crate::virtual_novel::new_toc_url().unwrap();store_gate(root.path(),&prefix,7,false,None,&origin);let before=BTreeMap::from([(12,original.clone())]);let mut portable=original.clone();portable.toc_url=candidate.clone();let after=BTreeMap::from([(12,portable.clone())]);
    assert!(record_claim_guard_conn(root.path(),&connection,&before,None).unwrap().validate(&after).is_err());let mut guard=record_claim_guard_conn(root.path(),&connection,&before,None).unwrap();guard.authorize_virtual_rebind(&before,&fence,NovelId(12),&observed,&candidate).unwrap();guard.validate(&after).unwrap();assert!(guard.validate(&before).is_err());assert!(guard.validate(&BTreeMap::new()).is_err());let actual_origin=crate::native::object_store::read_fs_gate_origin(root.path(),&prefix).unwrap().unwrap();assert_eq!(actual_origin,origin,"authorization must not persist candidate before metadata commits");
    let guard=record_claim_guard_conn(root.path(),&connection,&after,None).unwrap();let error=guard.validate(&before).unwrap_err().to_string();assert!(error.contains("immutable"),"{error}");let mut edited=portable.clone();edited.title="edit after portable commit and before origin repair".into();guard.validate(&BTreeMap::from([(12,edited)])).unwrap();let mut repair=record_claim_guard_conn(root.path(),&connection,&after,None).unwrap();repair.authorize_virtual_rebind(&after,&fence,NovelId(12),&observed,&candidate).unwrap();repair.validate(&after).unwrap();let other=crate::virtual_novel::new_toc_url().unwrap();assert!(repair.authorize_virtual_rebind(&after,&fence,NovelId(12),&candidate,&other).is_err());
}

#[test]
fn virtual_rebind_cannot_override_closed_stale_or_foreign_namespace_authority(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();let original=virtual_record(12);let prefix=prefix(&original);let fence=WriteFence::new(prefix.clone(),7);let observed=original.toc_url.clone();let origin=crate::db::novel_codec::fold(&observed);let candidate=crate::virtual_novel::new_toc_url().unwrap();let before=BTreeMap::from([(12,original.clone())]);for(closed,epoch,origin)in [(true,7,origin.clone()),(false,8,origin.clone()),(false,7,"https://example.test/foreign/".into())]{store_gate(root.path(),&prefix,epoch,closed,closed.then_some("foreign-owner"),&origin);let mut guard=record_claim_guard_conn(root.path(),&connection,&before,None).unwrap();assert!(guard.authorize_virtual_rebind(&before,&fence,NovelId(12),&observed,&candidate).is_err());}
    store_gate(root.path(),&prefix,7,false,None,&origin);let ancestor=ObjectPrefix::new(prefix.as_ref().rsplit_once('/').unwrap().0).unwrap();store_gate(root.path(),&ancestor,1,false,None,"https://example.test/ancestor/");let mut guard=record_claim_guard_conn(root.path(),&connection,&before,None).unwrap();guard.authorize_virtual_rebind(&before,&fence,NovelId(12),&observed,&candidate).unwrap();let mut changed=original;changed.toc_url=candidate;assert!(guard.validate(&BTreeMap::from([(12,changed)])).is_err());
}

#[test]
fn publication_marker_may_open_only_its_exact_closed_nonremoval_namespace(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();connection.execute_batch(SCHEMA).unwrap();let target=record(9);let prefix=prefix(&target);let owner="session:0:plan";claim(root.path(),&connection,&claims::PublicationClaim{owner,session:"session",publication:0,revision:"plan"},9,&target.toc_url,prefix.as_ref()).unwrap();let receipt=crate::application::transfer::PublicationReceipt{novel_ordinal:0,action:crate::application::transfer::PlanAction::Create,outcome:"created".into(),assigned_id:Some(9),files_installed:1,error:None};let marker=TransferCommitMarker{session_id:"session".into(),publication_id:0,novel_id:NovelId(9),receipt:serde_json::to_vec(&receipt).unwrap(),yaml_commit_path:"committed".into()};let after=BTreeMap::from([(9,target.clone())]);let origin=crate::db::novel_codec::fold(&target.toc_url);store_gate(root.path(),&prefix,4,true,Some(owner),&origin);record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),Some(&marker)).unwrap().validate(&after).unwrap();store_gate(root.path(),&prefix,4,true,Some("other-owner"),&origin);assert!(record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),Some(&marker)).unwrap().validate(&after).is_err());let removal=format!("remove-v1:9:0:{}",uuid::Uuid::new_v4());connection.execute("UPDATE native_transfer_target_claims SET owner=?1",[&removal]).unwrap();store_gate(root.path(),&prefix,4,true,Some(&removal),&origin);assert!(record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),Some(&marker)).unwrap().validate(&after).is_err());
}

fn physical_alias_records(root:&std::path::Path)->(NovelRecord,NovelRecord,ObjectPrefix,ObjectPrefix){
    let mut child=record(2);child.file_title="n1234ab".into();child.use_subdirectory=true;child.toc_url="https://example.test/child/".into();let child_prefix=prefix(&child);let group=child_prefix.as_ref().trim_end_matches('/').rsplit_once('/').unwrap().0.rsplit('/').next().unwrap();let mut parent=record(1);parent.file_title=group.into();parent.use_subdirectory=true;let parent_prefix=prefix(&parent);let flat=root.join(crate::downloader::types::ARCHIVE_ROOT_DIR).join(&parent.sitename).join(&parent.file_title);std::fs::create_dir_all(flat.join(&child.file_title)).unwrap();assert!(!crate::platform::access_fence::namespace_prefixes_overlap(parent_prefix.as_ref(),child_prefix.as_ref()));assert!(crate::native::object_store::namespace_physical_overlap(root,parent_prefix.as_ref(),child_prefix.as_ref()).unwrap());(parent,child,parent_prefix,child_prefix)
}

#[test]
fn physical_flat_alias_blocks_new_identity_source_and_removal_but_keeps_legacy_rows_editable(){
    let root=tempfile::tempdir().unwrap();let inventory=crate::db::inventory::Inventory::new(root.path().to_path_buf());let connection=Connection::open_in_memory().unwrap();let(parent,child,parent_prefix,_)=physical_alias_records(root.path());let before=BTreeMap::from([(2,child.clone())]);let all=BTreeMap::from([(1,parent.clone()),(2,child)]);assert!(record_claim_guard_conn(root.path(),&connection,&before,None).unwrap().validate(&all).is_err());assert!(assert_physical_records(&inventory,&before,NovelId(1),&parent_prefix).is_err());let path=inventory.inventory_path("database",crate::db::inventory::InventoryScope::Local);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(&path,serde_yaml::to_string(&all).unwrap()).unwrap();assert!(assert_physical_current_namespace(&inventory,None,NovelId(1),&parent_prefix).is_err());assert!(assert_source_namespace(&inventory,None,&connection,NovelId(1),&parent_prefix,&crate::db::novel_codec::fold(&parent.toc_url)).is_err());assert!(assert_removal_identity(&inventory,None,&connection,&WriteFence::new(parent_prefix,7),NovelId(1)).is_err());let guard=record_claim_guard_conn(root.path(),&connection,&all,None).unwrap();let mut edited=all.clone();edited.get_mut(&1).unwrap().title.push_str(" changed");guard.validate(&edited).unwrap();edited.get_mut(&1).unwrap().toc_url="https://example.test/new-parent/".into();assert!(guard.validate(&edited).is_err());
}

#[test]
fn physical_foreign_claim_and_retained_gate_cannot_be_annexed_by_disjoint_logical_prefix(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();connection.execute_batch(SCHEMA).unwrap();let(parent,child,parent_prefix,child_prefix)=physical_alias_records(root.path());claim(root.path(),&connection,&claims::PublicationClaim{owner:"child-owner",session:"session",publication:1,revision:"plan"},2,&child.toc_url,child_prefix.as_ref()).unwrap();assert!(claim(root.path(),&connection,&claims::PublicationClaim{owner:"parent-owner",session:"other",publication:0,revision:"plan"},1,&parent.toc_url,parent_prefix.as_ref()).is_err());let reservation=NovelIdReservation::new(NovelId(1),71);let fence=WriteFence::new(parent_prefix.clone(),7);assert!(reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&parent.toc_url,false).is_err());connection.execute("DELETE FROM native_transfer_target_claims",[]).unwrap();store_gate(root.path(),&child_prefix,2,false,None,&crate::db::novel_codec::fold(&child.toc_url));assert!(reserve_ordinary_claim_conn(root.path(),&connection,&fence,&reservation,&parent.toc_url,false).is_err());assert!(record_claim_guard_conn(root.path(),&connection,&BTreeMap::new(),None).unwrap().validate(&BTreeMap::from([(1,parent)])).is_err());
}

#[test]
fn retained_backup_requires_exact_open_origin_and_rejects_unpublished_claims(){
    let root=tempfile::tempdir().unwrap();let inventory=crate::db::inventory::Inventory::new(root.path().to_path_buf());let connection=Connection::open_in_memory().unwrap();let record=record(12);let prefix=prefix(&record);assert!(assert_retained_source_namespace(&inventory,None,&connection,&prefix).is_err());store_gate(root.path(),&prefix,7,false,None,"");assert!(assert_retained_source_namespace(&inventory,None,&connection,&prefix).is_err());let origin=crate::db::novel_codec::fold(&record.toc_url);store_gate(root.path(),&prefix,7,false,None,&origin);assert_retained_source_namespace(&inventory,None,&connection,&prefix).unwrap();let reservation=NovelIdReservation::new(NovelId(12),71);reserve_ordinary_claim_conn(root.path(),&connection,&WriteFence::new(prefix.clone(),7),&reservation,&record.toc_url,false).unwrap();assert!(assert_retained_source_namespace(&inventory,None,&connection,&prefix).is_err());release_ordinary_claim_conn(&connection,12,71).unwrap();assert_retained_source_namespace(&inventory,None,&connection,&prefix).unwrap();store_gate(root.path(),&prefix,8,true,Some("remove-v1:12:7:pending"),&origin);assert!(assert_retained_source_namespace(&inventory,None,&connection,&prefix).is_err());store_gate(root.path(),&prefix,9,false,None,&origin);let path=inventory.inventory_path("database",crate::db::inventory::InventoryScope::Local);std::fs::create_dir_all(path.parent().unwrap()).unwrap();std::fs::write(path,serde_yaml::to_string(&BTreeMap::from([(12,record)])).unwrap()).unwrap();assert!(assert_retained_source_namespace(&inventory,None,&connection,&prefix).is_err());
}

#[test]
fn committed_virtual_origin_lag_is_readonly_until_exact_affected_retirement_repairs_it(){
    let root=tempfile::tempdir().unwrap();let inventory=crate::db::inventory::Inventory::new(root.path().to_path_buf());let connection=Connection::open_in_memory().unwrap();let mut current=virtual_record(12);let legacy=current.toc_url.clone();current.toc_url=crate::virtual_novel::new_toc_url().unwrap();let prefix=prefix(&current);let fence=WriteFence::new(prefix.clone(),7);let origin=crate::db::novel_codec::fold(&current.toc_url);let path=inventory.inventory_path("database",crate::db::inventory::InventoryScope::Local);std::fs::create_dir_all(path.parent().unwrap()).unwrap();let before=BTreeMap::from([(12,current.clone())]);std::fs::write(&path,serde_yaml::to_string(&before).unwrap()).unwrap();store_gate(root.path(),&prefix,7,false,None,&legacy);let guard=record_claim_guard_conn(root.path(),&connection,&before,None).unwrap();guard.validate(&before).unwrap();assert_source_namespace(&inventory,None,&connection,NovelId(12),&prefix,&origin).unwrap();assert_eq!(crate::native::object_store::read_fs_gate_origin(root.path(),&prefix).unwrap().as_deref(),Some(legacy.as_str()));let mut stale=before.clone();stale.get_mut(&12).unwrap().toc_url=legacy.clone();assert!(guard.validate(&stale).is_err());let mut wrong=before.clone();wrong.get_mut(&12).unwrap().ncode=Some(crate::virtual_novel::ncode(99));std::fs::write(&path,serde_yaml::to_string(&wrong).unwrap()).unwrap();assert!(assert_source_namespace(&inventory,None,&connection,NovelId(12),&prefix,&origin).is_err());assert!(assert_removal_identity(&inventory,None,&connection,&fence,NovelId(12)).is_err());assert_eq!(crate::native::object_store::read_fs_gate_origin(root.path(),&prefix).unwrap().as_deref(),Some(legacy.as_str()));std::fs::write(&path,serde_yaml::to_string(&before).unwrap()).unwrap();assert_removal_identity(&inventory,None,&connection,&fence,NovelId(12)).unwrap();assert_eq!(crate::native::object_store::read_fs_gate_origin(root.path(),&prefix).unwrap().as_deref(),Some(origin.as_str()));
}

#[test]
fn explicit_virtual_authorization_cannot_move_the_current_prefix_or_ncode(){
    let root=tempfile::tempdir().unwrap();let connection=Connection::open_in_memory().unwrap();let original=virtual_record(12);let prefix=prefix(&original);let fence=WriteFence::new(prefix.clone(),7);let legacy=original.toc_url.clone();store_gate(root.path(),&prefix,7,false,None,&legacy);let candidate=crate::virtual_novel::new_toc_url().unwrap();let before=BTreeMap::from([(12,original.clone())]);let mut guard=record_claim_guard_conn(root.path(),&connection,&before,None).unwrap();guard.authorize_virtual_rebind(&before,&fence,NovelId(12),&legacy,&candidate).unwrap();let mut moved=original.clone();moved.toc_url=candidate.clone();moved.file_title="another-folder".into();assert!(guard.validate(&BTreeMap::from([(12,moved)])).is_err());let mut changed=original;changed.toc_url=candidate;changed.ncode=Some(crate::virtual_novel::ncode(99));assert!(guard.validate(&BTreeMap::from([(12,changed)])).is_err());
}

#[test]
fn sqlite_epoch_reads_are_checked_and_preserve_the_integer_boundary(){
    let connection=Connection::open_in_memory().unwrap();
    for epoch in [0_i64,i64::MAX]{let actual=connection.query_row("SELECT ?1",[epoch],|row|epoch_from_sql(row,0)).unwrap();assert_eq!(actual,u64::try_from(epoch).unwrap());}
    let negative=connection.query_row("SELECT -1",[],|row|epoch_from_sql(row,0));
    assert!(matches!(negative,Err(rusqlite::Error::FromSqlConversionFailure(0,rusqlite::types::Type::Integer,_))));
}

#[test]
fn sqlite_origin_repair_rejects_epoch_overflow_without_mutation(){
    let connection=Connection::open_in_memory().unwrap();connection.execute_batch("CREATE TABLE novel_access_gates(prefix TEXT PRIMARY KEY,epoch INTEGER NOT NULL CHECK(epoch>=0),closed INTEGER NOT NULL,origin_url_fold TEXT NOT NULL);").unwrap();
    let prefix=ObjectPrefix::new("novels/Test/book").unwrap();let legacy="https://narou.rs/virtual/vs_12";let current=crate::virtual_novel::new_toc_url().unwrap();connection.execute("INSERT INTO novel_access_gates(prefix,epoch,closed,origin_url_fold) VALUES(?1,?2,0,?3)",rusqlite::params![prefix.as_ref().trim_end_matches('/'),i64::MAX,legacy]).unwrap();
    let maximum=u64::try_from(i64::MAX).unwrap();let oversized=maximum.checked_add(1).unwrap();let error=repair_virtual_legacy_origin(std::path::Path::new(""),&connection,&prefix,oversized,legacy,&current).unwrap_err();assert!(error.to_string().contains("SQLite integer range"));
    let unchanged:(i64,String)=connection.query_row("SELECT epoch,origin_url_fold FROM novel_access_gates",[],|row|Ok((row.get(0)?,row.get(1)?))).unwrap();assert_eq!(unchanged,(i64::MAX,legacy.to_owned()));
    repair_virtual_legacy_origin(std::path::Path::new(""),&connection,&prefix,maximum,legacy,&current).unwrap();assert_eq!(connection.query_row("SELECT origin_url_fold FROM novel_access_gates",[],|row|row.get::<_,String>(0)).unwrap(),current);
}


#[test]
fn physical_identity_resolves_through_the_canonical_root_spelling_for_claim_consumers(){
    let dir=tempfile::tempdir().unwrap();let canonical=std::fs::canonicalize(dir.path()).unwrap();let(_parent,child,parent_prefix,child_prefix)=physical_alias_records(dir.path());
    // Windows canonicalizes to a `\\?\`-verbatim spelling; `key()` must not
    // reject namespaces simply because the caller's root differs from the
    // canonical form resolved paths are emitted in.
    #[cfg(windows)]
    assert!(canonical.as_os_str().to_string_lossy().starts_with("\\\\?\\"),"regression needs the verbatim root spelling, got {}",canonical.display());
    let root=canonical.as_path();let inventory=crate::db::inventory::Inventory::new(root.to_path_buf());let connection=Connection::open_in_memory().unwrap();connection.execute_batch(SCHEMA).unwrap();
    assert_physical_records(&inventory,&BTreeMap::new(),NovelId(3),&prefix(&record(3))).unwrap();
    claim(root,&connection,&claims::PublicationClaim{owner:"session:0:canon",session:"session",publication:0,revision:"plan"},3,"https://example.test/canon/",prefix(&record(3)).as_ref()).unwrap();
    claim(root,&connection,&claims::PublicationClaim{owner:"session:1:canon",session:"session",publication:1,revision:"plan"},2,&child.toc_url,child_prefix.as_ref()).unwrap();
    assert_physical_records(&inventory,&BTreeMap::from([(2,child)]),NovelId(1),&parent_prefix).unwrap_err();
}
